import * as React from "react";
import "./Verify.scss";
import Verified from "./Verified/Verified";

export interface VerifyProps {
  /**
   * Indicates whether verification status is confirmed
   */
  verified: boolean;

  /**
   * Customisable text/component for verification prompt.
   * Defaults to "Verify" if not provided
   */
  verifyLabel?: React.ReactNode;

  /**
   * Callback function triggered when user initiates verification.
   * Optional - only used in unverified state
   */
  onClick?: () => void;
}

export const Verify: React.FC<VerifyProps> = ({
  verified,
  verifyLabel = "Verify",
  onClick,
}) => {
  const handleClick = (e: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
    e.stopPropagation();
    onClick?.();
  };

  return (
    <div className="verify-container">
      {verified ? (
        <Verified />
      ) : (
        <div className="verify-label-container" onClick={handleClick}>
          {verifyLabel}
        </div>
      )}
    </div>
  );
};

export default Verify;
